  function openDeepLinkedFollowup(){const id=state.deepLinkFollowupId;if(!id)return;if(window.carestepHomeNavigation?.allowsNotificationFocus?.('hospital')===false){state.deepLinkFollowupId='';return;}const item=state.followups.find(x=>x.id===id);if(item)window.carestepHomeCare?.selectPatient?.(item.patientId);window.carestepHomeNavigation?.go('hospital',{scroll:false});if($('homeCareAll'))$('homeCareAll').open=true;state.followupFilter='all';renderFollowups();requestAnimationFrame(()=>{const details=$('homeFollowupList')?.querySelector(`[data-followup-details="${CSS.escape(id)}"]`);if(!details)return;details.open=true;details.closest('.home-followup-card')?.scrollIntoView({behavior:'smooth',block:'center'});state.deepLinkFollowupId='';const url=new URL(location.href);url.searchParams.delete('followup');history.replaceState({},'',url.pathname+url.search);});}
