  const FOLLOWUP_RESPONSE_LABEL={good:'괜찮아요',watch:'관찰이 필요해요',concern:'병원 상담이 필요해요'};
  function followupDateState(item){if(item.responseCode==='concern'&&((Number(item.consultation?.clinicReplyCount)||0)===0||(Number(item.consultation?.unreadCount)||0)>0))return 'attention';if(item.status==='completed')return 'completed';if(item.dueDate<today())return 'overdue';if(item.dueDate===today())return 'today';return 'upcoming';}
