  async function submitFollowupResponse(event){event.preventDefault();const form=event.currentTarget,id=form.dataset.followupResponse,editing=form.dataset.responseMode==='edit',selected=form.querySelector('input[type="radio"]:checked'),note=form.querySelector('textarea').value.trim(),button=form.querySelector('button[type="submit"]'),out=form.querySelector('.home-followup-response-status');if(!selected){out.textContent='현재 상태를 선택해주세요.';return;}button.disabled=true;button.textContent=editing?'수정 저장 중…':'전달 중…';out.textContent='';try{await api('/home/followups/'+encodeURIComponent(id)+'/respond',{method:editing?'PUT':'POST',body:JSON.stringify({responseCode:selected.value,note})});state.editingFollowupResponseId='';delete state.consultations[id];await loadFollowups();}catch(e){if(e.status===409){state.editingFollowupResponseId='';await loadFollowups();alert(e.message||'병원 확인이 시작되어 수정할 수 없습니다.');return;}out.textContent=e.message||'응답을 전달하지 못했습니다.';button.disabled=false;button.textContent=editing?'수정 저장':'확인 완료';}}
