    section.innerHTML=`<div class="home-step">CARESTEP HOME · 연결</div><h1 id="joinHeading">병원과 연결하기</h1><p id="joinLead" class="home-lead"></p><div id="joinLoggedIn" hidden><p id="joinAccount"></p><label class="home-access-field">연결할 환자 이름<input id="joinExistingPatient" maxlength="80" autocomplete="off"></label><button id="joinWithAccount" class="home-primary" type="button">이 계정으로 연결 요청</button><button id="joinChangeAccount" class="home-text-button" type="button">다른 계정으로 로그인</button></div><form id="homeJoinForm"><label class="home-access-field">보호자 이름<input id="joinName" maxlength="80" autocomplete="name" required></label><label class="home-access-field" id="joinPatientField">연결할 환자 이름<input id="joinPatient" maxlength="80" autocomplete="off"></label><label class="home-access-field">내 휴대전화 번호<div class="home-access-inline"><input id="joinPhone" type="tel" inputmode="tel" autocomplete="tel" maxlength="13" required><button id="joinSendCode" class="home-secondary" type="button">인증번호 받기</button></div></label><label class="home-access-field">문자로 받은 인증번호<input id="joinCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><p class="home-help">인증번호는 5분 동안 한 번 사용할 수 있습니다.</p><label class="home-access-field">Home 비밀번호<input id="joinPassword" type="password" autocomplete="new-password" minlength="8" required></label><label class="home-access-consent"><input id="joinTerms" type="checkbox" required><span>CARESTEP Home 이용약관에 동의합니다.</span></label><label class="home-access-consent"><input id="joinPrivacy" type="checkbox" required><span>가입 정보의 저장·병원 전달 및 연결된 환자의 건강기록·자료·가족 공동 기록 이용에 동의합니다.</span></label><button id="joinSubmit" class="home-primary" type="submit">가입하고 연결 요청</button><button id="joinLogin" class="home-text-button" type="button">이미 가입했다면 로그인</button></form><div id="joinStatus" class="home-status" role="status" aria-live="polite"></div><button id="joinHome" class="home-text-button" type="button">Home으로 돌아가기</button>`;
    ($('loginView')?.parentElement||document.body).append(section);views.push('joinView');const legal=document.querySelector('#inviteView .home-legal')?.cloneNode(true);if(legal)$('joinTerms').closest('label').before(legal);
    $('joinSendCode').onclick=homeAccessCode;$('homeJoinForm').onsubmit=homeAccessRegister;
    $('joinPhone').oninput=()=>{homeJoinState.challengeId='';$('joinCode').value='';};
    $('joinLogin').onclick=()=>show('loginView');$('joinChangeAccount').onclick=async()=>{await logout();show('loginView');};
    $('joinWithAccount').onclick=homeAccessAccept;$('joinHome').onclick=()=>{homeAccessClear();restore();};
    const family=document.createElement('dialog');family.id='homeFamilyDialog';family.className='home-family-dialog';family.innerHTML=`<div class="home-family-heading"><div><div class="home-step">함께 돌보기</div><h2 id="familyHeading">가족 보호자</h2></div><button id="familyClose" class="home-secondary" type="button" aria-label="가족 관리 닫기">닫기</button></div><div id="familyBody"></div><div id="familyStatus" class="home-status" role="status"></div>`;document.body.append(family);
    const close=()=>{homeJoinState.revision++;homeJoinState.patientId='';family.close();$('familyBody').replaceChildren();};$('familyClose').onclick=close;family.addEventListener('cancel',e=>{e.preventDefault();close();});
